action.command:
cd /workspace; cat > /tmp/ldap_check.php <<'PHP'
<?php
require '/var/www/html/vendor/autoload.php';
$l = Dsl\App\Tools\LdapUtility::getInstance();
echo "connect=" . var_export($l->connect(), true) . PHP_EOL;
echo "bind=" . var_export($l->bind(), true) . PHP_EOL;
echo "search=" . var_export($l->search(null, '(objectClass=inetOrgPerson)'), true) . PHP_EOL;
$e = $l->getEntries();
echo "entries=" . count($e) . PHP_EOL;
$l->disconnect();
PHP
docker cp /tmp/ldap_check.php ddev-tfm-fachplanung-web:/tmp/ldap_check.php
docker exec ddev-tfm-fachplanung-web bash -c 'cd /var/www/html && php /tmp/ldap_check.php' 2>&1 | tail -20

